import{_ as e,o as t,c as o,a2 as i}from"./chunks/framework.mRCPFc5l.js";const s="/images/relay/flow.svg",g=JSON.parse('{"title":"API 中转","description":"","frontmatter":{},"headers":[],"relativePath":"relay/index.md","filePath":"relay/index.md","lastUpdated":1786861842000}'),l={name:"relay/index.md"};function r(n,a,p,d,c,h){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="api-中转" tabindex="-1">API 中转 <a class="header-anchor" href="#api-中转" aria-label="Permalink to &quot;API 中转&quot;">​</a></h1><p>通过两颗枣树提供的 API 地址，已安装的 Codex CLI 或 Codex Desktop 可以直接使用控制台分组。你只需要创建一个 API Key，再把控制台生成的配置放进 Codex。</p><div class="tip custom-block"><p class="custom-block-title">本文档适用范围</p><p>本文只介绍客户侧操作，不包含服务端部署、上游账号管理或后台配置。</p></div><h2 id="开始前" tabindex="-1">开始前 <a class="header-anchor" href="#开始前" aria-label="Permalink to &quot;开始前&quot;">​</a></h2><ul><li>已拿到服务账号，并能登录控制台。</li><li>本机已经安装 Codex CLI 或 Codex Desktop。</li><li>你知道要使用的 Codex 分组；可用分组和模型以控制台显示为准。</li></ul><h2 id="四步完成配置" tabindex="-1">四步完成配置 <a class="header-anchor" href="#四步完成配置" aria-label="Permalink to &quot;四步完成配置&quot;">​</a></h2><ol><li>在 <strong>API 密钥</strong> 页面<a href="/relay/api-keys">创建 API Key</a>。</li><li>在密钥列表点击 <strong>使用密钥</strong>，选择 <strong>Codex</strong>。</li><li>按操作系统复制控制台生成的配置。</li><li>完全退出并重启 Codex，发送一个最小测试请求。</li></ol><h2 id="服务地址" tabindex="-1">服务地址 <a class="header-anchor" href="#服务地址" aria-label="Permalink to &quot;服务地址&quot;">​</a></h2><p>控制台地址：<a href="https://liangkezaoshu.top/" target="_blank" rel="noreferrer">https://liangkezaoshu.top/</a></p><p>API 密钥页面显示的 API 端点是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://liangkezaoshu.top/v1</span></span></code></pre></div><p>只使用控制台显示的地址和“使用密钥”生成的内容，不要从旧教程中拼接地址、认证字段或模型名。</p><h2 id="请求关系" tabindex="-1">请求关系 <a class="header-anchor" href="#请求关系" aria-label="Permalink to &quot;请求关系&quot;">​</a></h2><figure class="doc-figure"><img src="'+s+'" alt="Codex 通过 API Key 访问两颗枣树中转并转发到模型分组"><figcaption>客户端、API 中转和模型分组之间的请求关系。</figcaption></figure><p>分组决定可用模型、额度和计费方式；这些内容可能随服务配置变化，页面实际显示优先于本文示例。</p><p>请求成功后，可在左侧 <strong>使用记录</strong> 中按时间、模型和状态码核对调用；如果没有任何记录，通常说明 Codex 仍在使用旧配置。</p><div class="warning custom-block"><p class="custom-block-title">密钥安全</p><p>API Key 等同于调用凭据。只在可信设备上复制，不要把完整密钥放进 Git、截图、日志、公开 Issue 或聊天记录；反馈问题时只提供末四位。</p></div>',17)])])}const x=e(l,[["render",r]]);export{g as __pageData,x as default};
